-- Wrap in BEGIN/ROLLBACK. Synthetic fixtures and queue entries must never commit.
do $test$
declare owner_id uuid; sid uuid:=gen_random_uuid(); pid uuid:=gen_random_uuid(); wa text:='263'||lpad((floor(random()*1e11)::bigint)::text,11,'0'); other_wa text:='263'||lpad((floor(random()*1e11)::bigint)::text,11,'0'); q jsonb; oid uuid; cid uuid; other_cid uuid; aid uuid:=gen_random_uuid(); version text; original_stock int:=4; n int; state_copy jsonb; denied boolean;
begin
 select sh.owner_id into owner_id from public.shops sh where sh.owner_id is not null limit 1;
 if owner_id is null then raise exception 'An existing shop owner fixture is required';end if;
 select t.version into version from public.terms_and_conditions t where is_active order by created_at desc limit 1;
 if version is null then raise exception 'Active terms are required';end if;
 update public.whatsapp_bot_config set enabled=true where id;
 update public.delivery_pricing_settings set enabled=false where id;
 insert into public.shops(id,owner_id,name,slug,status,is_available,delivery_fee,accepted_payment_methods,operating_hours,contact_email,contact_phone) values(sid,owner_id,'Rollback WhatsApp shop','wa-test-'||sid,'active',true,3,'["pay_on_delivery"]'::jsonb,null,'wa-shop@example.invalid','test-phone');
 insert into public.shop_service_locations(shop_id,location_name,location_type) values(sid,'Rollback Town','town');
 insert into public.shop_products(id,shop_id,name,price,stock,status,is_available) values(pid,sid,'Rollback WhatsApp bread',2.50,original_stock,'active',true);
 if has_function_privilege('anon','public.whatsapp_bot_message(text,text,text,text,numeric,numeric,text,timestamptz)','EXECUTE') or has_table_privilege('authenticated','public.whatsapp_bot_sessions','SELECT') then raise exception 'WhatsApp financial state is exposed';end if;
 perform public.whatsapp_bot_message('hello-'||wa,wa,'text','hello');
 perform public.whatsapp_bot_message('shops-'||wa,wa,'interactive','shops');
 perform public.whatsapp_bot_message('town-'||wa,wa,'text','Rollback Town');
 perform public.whatsapp_bot_message('shop-'||wa,wa,'interactive','shop:'||sid);
 perform public.whatsapp_bot_message('product-'||wa,wa,'interactive','product:'||pid);
 q:=public.whatsapp_bot_message('quantity-'||wa,wa,'text','2');
 if q->>'text' not like '%2 × Rollback WhatsApp bread%' then raise exception 'Product quantity not shown';end if;
 q:=public.whatsapp_bot_message('checkout-'||wa,wa,'interactive','checkout');
 if q->>'kind'<>'location_request' then raise exception 'GPS not requested';end if;
 perform public.whatsapp_bot_message('location-'||wa,wa,'location','',-17.8,31.0);
 perform public.whatsapp_bot_message('address-'||wa,wa,'text','Synthetic test address');
 perform public.whatsapp_bot_message('name-'||wa,wa,'text','Synthetic WhatsApp shopper');
 q:=public.whatsapp_bot_message('payment-'||wa,wa,'interactive','payment:pay_on_delivery');
 if q->>'text' not like '%Terms and Privacy%' then raise exception 'Terms not offered';end if;
 q:=public.whatsapp_bot_message('agree-'||wa,wa,'interactive','agree');
 if q->>'text' not like '%Total: $8.00%' then raise exception 'Server price/fee calculation incorrect';end if;
 q:=public.whatsapp_bot_message('confirm-'||wa,wa,'interactive','confirm');
 oid:=(q->>'order_id')::uuid;
 if oid is null then raise exception 'Native WhatsApp order not created: %',q->>'text';end if;
 if (select total_amount from public.shop_orders where id=oid)<>8 or (select stock from public.shop_products where id=pid)<>2 then raise exception 'Authoritative total or stock reservation failed';end if;
 q:=public.whatsapp_bot_message('confirm-'||wa,wa,'interactive','confirm');
 if (q->>'order_id')::uuid<>oid then raise exception 'Duplicate message changed its order';end if;
 perform public.whatsapp_bot_message('second-confirm-'||wa,wa,'interactive','confirm');
 if (select count(*) from public.whatsapp_bot_orders where wa_id=wa)<>1 or (select stock from public.shop_products where id=pid)<>2 then raise exception 'Duplicate confirmation placed/reserved twice';end if;
 perform public.whatsapp_bot_message('hello-'||other_wa,other_wa,'text','hello');
 q:=public.whatsapp_bot_message('steal-order-'||other_wa,other_wa,'interactive','order:'||oid);
 if q->>'text' not like '%not found%' or q->>'text' like '%Synthetic%' then raise exception 'Another sender could read the order';end if;
 perform public.whatsapp_bot_message('cancel-'||wa,wa,'interactive','cancel_order:'||oid);
 perform public.whatsapp_bot_message('cancel-again-'||wa,wa,'interactive','cancel_order:'||oid);
 if (select stock from public.shop_products where id=pid)<>original_stock or (select status from public.shop_orders where id=oid)<>'cancelled' then raise exception 'Cancellation did not restore stock exactly once';end if;
 select customer_id into cid from public.whatsapp_bot_customers where wa_id=wa;
 if cid is null or not exists(select 1 from public.customers where id=cid and phone_verified and terms_accepted and terms_version=version) then raise exception 'New customer terms/verified phone missing';end if;
 state_copy:=jsonb_build_object('step','payment','town','Rollback Town','shop_id',sid,'shop_name','Rollback WhatsApp shop','cart',jsonb_build_array(jsonb_build_object('id',pid,'qty',2)),'latitude',-17.8,'longitude',31,'address','Synthetic test address','name','Synthetic WhatsApp shopper','payment','pay_on_delivery','terms_agreed',version);
 update public.whatsapp_bot_sessions set state=state_copy where wa_id=wa;
 perform public.whatsapp_bot_message('review-again-'||wa,wa,'text','review');
 update public.shop_products set price=3.5 where id=pid;
 q:=public.whatsapp_bot_message('stale-price-'||wa,wa,'interactive','confirm');
 if q->>'order_id' is not null or q->>'text' not like '%confirm again%' then raise exception 'Changed product price charged without reconfirmation';end if;
 update public.shop_products set stock=0 where id=pid;
 q:=public.whatsapp_bot_message('sold-out-'||wa,wa,'interactive','confirm');
 if q->>'order_id' is not null or (select count(*) from public.whatsapp_bot_orders where wa_id=wa)<>1 then raise exception 'Out-of-stock checkout was accepted';end if;
 q:=public.whatsapp_bot_message('bad-id-'||wa,wa,'interactive','product:not-a-uuid');
 if q is null then raise exception 'Malformed menu input did not recover';end if;
 update public.whatsapp_bot_sessions set state=state_copy where wa_id=wa;
 update public.shop_products set stock=original_stock,status='active',is_available=true where id=pid;
 -- An existing account is never claimed just by matching an editable public phone.
 insert into public.customers(username,phone_number,full_name,latitude,longitude) values('wa-collision-'||other_wa,'+'||other_wa,'Synthetic existing customer',0,0) returning id into other_cid;
 update public.whatsapp_bot_sessions set state=state_copy where wa_id=other_wa;
 q:=public.whatsapp_bot_message('collision-review-'||other_wa,other_wa,'text','review');
 if (select state->>'step' from public.whatsapp_bot_sessions where wa_id=other_wa)<>'review' then raise exception 'Collision review failed: %, stock/price=%, cart=%',q,(select jsonb_build_object('stock',stock,'price',price,'available',is_available,'status',status) from public.shop_products where id=pid),(select state->'cart' from public.whatsapp_bot_sessions where wa_id=other_wa);end if;
 q:=public.whatsapp_bot_message('collision-confirm-'||other_wa,other_wa,'interactive','confirm');
 if q->>'order_id' is not null or (select state->>'step' from public.whatsapp_bot_sessions where wa_id=other_wa)<>'account_link' or exists(select 1 from public.whatsapp_bot_customers where wa_id=other_wa) then raise exception 'Phone collision test: reply=%, step=%, bound=%',q,(select state->>'step' from public.whatsapp_bot_sessions where wa_id=other_wa),exists(select 1 from public.whatsapp_bot_customers where wa_id=other_wa);end if;
 denied:=false;begin perform public.whatsapp_bot_admin('invalid','invalid','link',jsonb_build_object('wa_id',other_wa,'customer_id',other_cid));exception when others then denied:=true;end;
 if not denied then raise exception 'Invalid admin linked a WhatsApp identity';end if;
 insert into public.admins(id,username,password_hash) values(aid,'wa_test_'||aid,'rollback-test-only');
 perform public.whatsapp_bot_admin('wa_test_'||aid,'rollback-test-only','link',jsonb_build_object('wa_id',other_wa,'customer_id',other_cid));
 perform public.whatsapp_bot_message('linked-checkout-'||other_wa,other_wa,'interactive','checkout');
 perform public.whatsapp_bot_message('linked-payment-'||other_wa,other_wa,'interactive','payment:pay_on_delivery');
 q:=public.whatsapp_bot_message('linked-confirm-'||other_wa,other_wa,'interactive','confirm');
 if q->>'order_id' is null or not exists(select 1 from public.shop_orders where id=(q->>'order_id')::uuid and customer_id=other_cid) then raise exception 'Verified account could not complete a native order';end if;
 -- The old payment table is browser writable: its URLs/status must not be trusted.
 update public.shop_orders set payment_method='paynow' where id=oid;
 insert into public.paynow_transactions(reference,payment_type,entity_id,amount,status,paynow_payment_url) values('WA-'||oid::text,'marketplace_order',oid,8,'paid','https://www.paynow.co.zw/FAKE-MERCHANT');
 q:=public.whatsapp_bot_message('forged-payment-'||wa,wa,'interactive','order:'||oid);
 if q->>'text' like '%FAKE-MERCHANT%' or q->>'text' like '%Paynow status: paid%' then raise exception 'Untrusted payment record was shown as authoritative';end if;
 -- Large baskets must retain their final total and confirmation instructions.
 for n in 1..30 loop
  insert into public.shop_products(shop_id,name,price,stock,status,is_available) values(sid,repeat('Long product name ',8)||n,1,1000,'active',true);
 end loop;
 update public.whatsapp_bot_sessions set state=state_copy||jsonb_build_object('address',repeat('A',300),'cart',(select jsonb_agg(jsonb_build_object('id',id,'qty',1000)) from public.shop_products where shop_id=sid and name like 'Long product name %')) where wa_id=wa;
 q:=public.whatsapp_bot_message('large-review-'||wa,wa,'text','review');
 if length(q->>'text')>3800 or q->>'text' not like '%Total: $30003.00%' or q->>'text' not like '%Select Confirm order%' then raise exception 'Large basket hid checkout totals or confirmation';end if;
 update public.whatsapp_bot_sessions set state=state_copy where wa_id=wa;
 update public.delivery_pricing_settings set enabled=true where id;
 q:=public.whatsapp_bot_message('quote-required-'||wa,wa,'text','review');
 if q->>'text' not like '%quotes are required%' then raise exception 'Bot bypassed the approved quote workflow';end if;
 if not exists(select 1 from public.business_activity_events e join public.business_activity_email_deliveries d on d.event_id=e.id where e.entity_table='shop_orders' and e.entity_id=oid::text and d.recipient_email='unilinkbase@gmail.com') then raise exception 'Order did not alert UniLink';end if;
 if exists(select 1 from public.business_activity_events where entity_table='whatsapp_bot_messages' and snapshot::text like '%Synthetic test address%') then raise exception 'Private WhatsApp contents leaked into activity email';end if;
end $test$;
